import{_ as a,o,c as s,a0 as l}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"第 19 章 · 用 AI 写策略的正确姿势","description":"","frontmatter":{},"headers":[],"relativePath":"book/part3/ch19.md","filePath":"book/part3/ch19.md","lastUpdated":1788537144000}'),i={name:"book/part3/ch19.md"};function r(c,t,e,n,p,h){return o(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="第-19-章-·-用-ai-写策略的正确姿势" tabindex="-1">第 19 章 · 用 AI 写策略的正确姿势 <a class="header-anchor" href="#第-19-章-·-用-ai-写策略的正确姿势" aria-label="Permalink to &quot;第 19 章 · 用 AI 写策略的正确姿势&quot;">​</a></h1><div class="ob-meta"><span class="chip">第三篇 · 实战篇</span><span class="chip">⏱ 精读约 50 分钟</span><span class="chip hot">🤖 AI 主线</span><span class="ob-wip">写作中</span></div><div class="tip custom-block"><p class="custom-block-title">🎯 学完这章你能</p><ul><li>掌握&quot;人机分工&quot;的策略开发工作流：人定逻辑，AI 写码，机器验证</li><li>拿到策略开发全流程的提示词骨架（完整模板库在 <a href="/book/part4/ch22.html">第 22 章</a>）</li></ul></div><h2 id="小节骨架-写作大纲" tabindex="-1">小节骨架（写作大纲） <a class="header-anchor" href="#小节骨架-写作大纲" aria-label="Permalink to &quot;小节骨架（写作大纲）&quot;">​</a></h2><ol><li><strong>AI 在策略开发中的正确岗位</strong>：初级程序员 + 讲解员 + 陪练，<strong>不是基金经理</strong></li><li><strong>工作流总览</strong>：想法 → 人写策略逻辑说明书 → AI 转代码 → 机器体检 → 人工复核</li><li><strong>&quot;策略逻辑说明书&quot;写法</strong>：让 AI 不猜的关键——标的、信号、仓位、成本、边界条件全写死</li><li><strong>实战演示</strong>：一个想法从 prompt 到可回测代码的完整过程（含失败迭代）</li><li><strong>能力边界</strong>：哪些环节 AI 靠谱（样板代码/指标计算/报错排查），哪些环节必须人来（逻辑审题/过拟合直觉/常识判断）</li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ 本书的铁律</p><p>AI 生成的每一行策略代码，在通过 <a href="/book/part3/ch20.html">第 20 章</a> 的验货流程之前，一律视为&quot;嫌疑代码&quot;。<strong>生成 ≠ 完成，验完 ≠ 完成，理解了才算完成。</strong></p></div><div class="info custom-block"><p class="custom-block-title">📋 自查清单（预告）</p><ul><li>[ ] 我写过一份完整的策略逻辑说明书</li><li>[ ] 我让 AI 逐行解释过它自己写的代码，并且我听懂了</li></ul></div><p>→ 下一章：<a href="/book/part3/ch20.html">第 20 章 · AI 生成代码验货指南 ⭐</a></p>',8)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
